168	// SendEvent processes an event payload in the detached subprocess.
169	// This is called by the hidden __send_analytics command.
170	func SendEvent(payloadJSON string) {
171		var payload EventPayload
172		if err := json.Unmarshal([]byte(payloadJSON), &payload); err != nil {
173			return
174		}
175	
176		// Create PostHog client - no need for fast timeouts since we're detached
177		// Read API key and endpoint from package-level vars (not passed via argv for security)
178		client, err := posthog.NewWithConfig(PostHogAPIKey, posthog.Config{
179			Endpoint:     PostHogEndpoint,
180			Logger:       silentLogger{},
181			DisableGeoIP: posthog.Ptr(true),
182		})
183		if err != nil {
184			return
185		}
186		defer func() {
187			_ = client.Close()
188		}()
189	
190		// Resolve the installed git version best-effort. A missing or failing
191		// git must never block the rest of the telemetry — the property is simply
192		// omitted when it can't be determined.
193		if v := gitVersion(context.Background()); v != "" {
194			if payload.Properties == nil {
195				payload.Properties = map[string]any{}
196			}
197			payload.Properties["git_version"] = v
198		}
199	
200		// Build properties
201		props := posthog.NewProperties()
202		for k, v := range payload.Properties {
203			props.Set(k, v)
204		}
205	
206		//nolint:errcheck // Best effort telemetry - don't block on result
207		_ = client.Enqueue(posthog.Capture{
208			DistinctId: payload.DistinctID,
209			Event:      payload.Event,
210			Properties: props,
211			Timestamp:  payload.Timestamp,
212		})
213	}
214	
215	// gitVersion returns the installed git version (e.g. "2.43.0"), best-effort.
216	// It returns "" when git is absent, the command fails or times out, or the
217	// output cannot be parsed — callers must treat "" as "unknown" and move on.
218	func gitVersion(ctx context.Context) string {
219		ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
220		defer cancel()
221	
222		out, err := exec.CommandContext(ctx, "git", "--version").Output()
223		if err != nil {
224			return ""
225		}
226		return parseGitVersion(string(out))
227	}
228	
229	// parseGitVersion extracts the version token from `git --version` output, which
230	// looks like "git version 2.43.0" (sometimes with a platform suffix such as
231	// "git version 2.39.3 (Apple Git-146)"). Returns "" if the shape is unexpected.
232	func parseGitVersion(out string) string {
233		fields := strings.Fields(out)
234		if len(fields) < 3 || fields[0] != "git" || fields[1] != "version" {
235			return ""
236		}
237		return fields[2]
238	}
